using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;
public static class DestinationT01Capture {
 public static object Before()=>Run("Before");public static object After()=>Run("After");
 static object Run(string prefix){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit scene required");var origin=new Vector3(-17.23132775f,-82,-1.074689f);var rot=Quaternion.LookRotation(new Vector3(-.242535625f,0,.9701425f));var output=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-08_B5_DestinationColors/T01/"));Directory.CreateDirectory(output);var players=s.GetRootGameObjects().Where(g=>g.name.StartsWith("Player")).SelectMany(g=>g.GetComponentsInChildren<Renderer>()).ToArray();var was=players.Select(r=>r.enabled).ToArray();foreach(var r in players)r.enabled=false;
 var shots=new[]{new{name="FloorDetail",p=new Vector3(.15f,1.65f,8.7f),t=new Vector3(1.15f,.01f,10.96f),fov=65f},new{name="ToSecurity",p=new Vector3(.10f,1.65f,1.40f),t=new Vector3(0,1.45f,13.8f),fov=76f},new{name="ToLab",p=new Vector3(-.1f,1.65f,12.1f),t=new Vector3(0,1.45f,-.4f),fov=76f},new{name="ServiceWall",p=new Vector3(-.65f,1.6f,5.0f),t=new Vector3(1.7f,1.35f,7.2f),fov=70f},new{name="Ceiling",p=new Vector3(.2f,1.7f,4.7f),t=new Vector3(.3f,3.1f,8.1f),fov=78f},new{name="SecurityPortal",p=new Vector3(.25f,1.65f,10.4f),t=new Vector3(0,1.50f,14.3f),fov=74f}};
 try{foreach(var shot in shots){var g=new GameObject("Temporary_T01_Review");var cam=g.AddComponent<Camera>();cam.transform.position=origin+rot*shot.p;cam.transform.LookAt(origin+rot*shot.t);cam.fieldOfView=shot.fov;cam.nearClipPlane=.035f;cam.farClipPlane=200;cam.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1600,1000,24){antiAliasing=4};var old=RenderTexture.active;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1000),0,0);tex.Apply();File.WriteAllBytes(output+prefix+"_"+shot.name+".png",tex.EncodeToPNG());RenderTexture.active=old;cam.targetTexture=null;UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);}}finally{for(int i=0;i<players.Length;i++)players[i].enabled=was[i];EditorSceneManager.OpenScene(s.path);}return new{prefix,images=shots.Length,output};}
}
